package com.cyclecare.app.rust
import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import com.cyclecare.app.data.local.*
import com.cyclecare.app.data.local.rust.*
import com.cyclecare.app.security.AuthPreferences
import kotlinx.coroutines.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import androidx.test.ext.junit.runners.AndroidJUnit4
import java.util.UUID
@RunWith(AndroidJUnit4::class)
class ErasureStorageRoomAndroidTest{
 private val context:Context=ApplicationProvider.getApplicationContext();private val handles=mutableListOf<CycleCareDatabase>();private val names=mutableListOf<String>();private val stages=listOf("rust_enrollment_rows","rust_enrollment_receipts","rust_enrollments")
 private fun open(mask:Int=7):CycleCareDatabase{val name="erase-${UUID.randomUUID()}";names+=name;return Room.databaseBuilder(context,CycleCareDatabase::class.java,name).allowMainThreadQueries().build().also{handles+=it;applyRustMetadataDraft(it.openHelper.writableDatabase);for(i in stages.indices)if(mask and(1 shl i)==0)it.openHelper.writableDatabase.execSQL("DROP TABLE ${stages[i]}")}}
 @After fun close(){handles.forEach{it.close()};names.forEach{context.deleteDatabase(it)}}
 private fun namespace(owner:String?)=owner?.takeIf{it.isNotBlank()}?.let(CycleCareDatabase::namespaceFor)?:"cycle_care_database"
 private fun syncOwner(owner:String?)=owner?.takeIf{it.isNotBlank()}?:"legacy_guest"
 private fun exists(db:CycleCareDatabase,table:String)=db.openHelper.writableDatabase.query("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",arrayOf(table)).use{it.moveToFirst()}
 private fun seed(db:CycleCareDatabase,owner:String?="owner"){
  val s=db.openHelper.writableDatabase;db.runInTransaction{RustDomainRows.write(s,"2026-10-01",RustDomainRows.Row.Log(CycleDayLog("2026-10-01",notes="synthetic 🌸/\n",bbtCelsius=Float.fromBits(Int.MIN_VALUE),sleepHours=Float.fromBits(1))));RustDomainRows.write(s,"settings",RustDomainRows.Row.Settings(CycleSettings(isOnboardingCompleted=true,averageCycleLength=33,isAppLockEnabled=true)));RustDomainRows.write(s,"profile",RustDomainRows.Row.Profile(OnboardingProfile(completedAtTimestamp=44,selectedGoalsCsv="synthetic")));s.execSQL("INSERT INTO rust_float_bits VALUES('orphan','synthetic',1,1)")
   for(o in listOf(syncOwner(owner),"other")){s.execSQL("INSERT INTO health_sync_outbox VALUES(?, 'op','2026-10-01','UPSERT',3,7,'synthetic','hash',2,0,0,NULL,NULL,NULL)",arrayOf(o));s.execSQL("INSERT INTO health_sync_revisions VALUES(?,'2026-10-01',7,'hash',0,1,9)",arrayOf(o));s.execSQL("INSERT INTO health_sync_cursors VALUES(?,99)",arrayOf(o));s.execSQL("INSERT INTO health_sync_conflicts VALUES(?,'2026-10-01','op',7,'synthetic','UPSERT',9,'remote',0,1,NULL,NULL)",arrayOf(o))}
   for(n in listOf(namespace(owner),"other")){s.execSQL("INSERT INTO rust_commit_receipts VALUES(?,'op','digest',1,'synthetic')",arrayOf(n));if(exists(db,stages[0]))s.execSQL("INSERT INTO rust_enrollment_rows(namespace,operation,record,payload,physical,revision,serverRevision,child) VALUES(?,'op','settings','synthetic','physical',7,9,'child')",arrayOf(n));if(exists(db,stages[1]))s.execSQL("INSERT INTO rust_enrollment_receipts VALUES(?,'op','settings','child',9,'hash',0)",arrayOf(n));if(exists(db,stages[2]))s.execSQL("INSERT INTO rust_enrollments VALUES(?,'op','binding',0,'STAGING','',1,'')",arrayOf(n))}
  }
 }
 private fun snapshot(db:CycleCareDatabase):List<List<String?>>{val out=mutableListOf<List<String?>>();for(table in listOf("rust_float_bits","cycle_day_logs","onboarding_profiles","cycle_settings","health_sync_revisions","health_sync_outbox","health_sync_conflicts","health_sync_cursors","rust_commit_receipts","rust_domain_epoch")+stages){out+=listOf(table);if(!exists(db,table)){out+=listOf("ABSENT");continue};db.openHelper.writableDatabase.query("SELECT * FROM $table ORDER BY 1,2").use{c->while(c.moveToNext())out+=(0 until c.columnCount).map{if(c.isNull(it))null else c.getString(it)}}};return out}
 private fun apply(db:CycleCareDatabase,native:Boolean,owner:String?="owner"){db.runInTransaction{val s=db.openHelper.writableDatabase;if(native)RustErasureStorage.apply(s,owner,syncOwner(owner))else RustErasureRows.apply(s,owner,syncOwner(owner))}}
 @Test fun fullDatabaseOriginalAllEightOptionalShapesOwnerGuestBlankAndRepeat(){RustTrackNative.warmUp();for(mask in 0..7)for(owner in listOf<String?>(null,"  ","owner")){val a=open(mask);val b=open(mask);seed(a,owner);seed(b,owner);apply(a,false,owner);apply(b,true,owner);assertEquals(snapshot(a),snapshot(b));assertEquals(CycleSettings(),(RustDomainRows.read(b.openHelper.writableDatabase,"settings")as RustDomainRows.Row.Settings).value);assertNull(RustDomainRows.read(b.openHelper.writableDatabase,"profile"));assertNull(RustDomainRows.read(b.openHelper.writableDatabase,"2026-10-01"));val s=b.openHelper.writableDatabase;for(table in listOf("health_sync_outbox","health_sync_revisions","health_sync_cursors","health_sync_conflicts")){s.query("SELECT count(*) FROM $table WHERE ownerId=?",arrayOf("other")).use{assertTrue(it.moveToFirst());assertEquals(1,it.getInt(0))}};apply(a,false,owner);apply(b,true,owner);assertEquals(snapshot(a),snapshot(b))}}
 @Test fun everyBeforeAfterSqlEffectRollsBackThenFreshRetryEqualsOriginal(){RustTrackNative.warmUp();val points=listOf("cycle_day_logs","onboarding_profiles","cycle_settings","rust_float_bits","health_sync_outbox","health_sync_revisions","health_sync_cursors","health_sync_conflicts","rust_commit_receipts")+stages+"defaults";for(timing in listOf("BEFORE","AFTER"))for(point in points){val a=open();val b=open();seed(a);seed(b);val s=b.openHelper.writableDatabase;val before=snapshot(b);val event=if(point=="defaults")"INSERT ON cycle_settings"else"DELETE ON $point";val whenClause=if(point=="rust_float_bits")" WHEN OLD.dateString='orphan'"else"";s.execSQL("CREATE TRIGGER fault $timing $event$whenClause BEGIN SELECT RAISE(ABORT,'erase fault'); END");assertNotNull("$timing/$point",runCatching{apply(b,true)}.exceptionOrNull());assertEquals(before,snapshot(b));s.execSQL("DROP TRIGGER fault");apply(b,true);apply(a,false);assertEquals(snapshot(a),snapshot(b))}}
 @Test fun privateSessionWrongIndexOrderThreadClosedReentryAndOutcome(){RustTrackNative.warmUp();val db=open(5);seed(db);val sql=db.openHelper.writableDatabase;val before=snapshot(db);val field=RustErasureStorage::class.java.getDeclaredField("entered").apply{isAccessible=true};@Suppress("UNCHECKED_CAST")val entered=field.get(RustErasureStorage)as ThreadLocal<Boolean>;val cls=Class.forName("com.cyclecare.app.data.local.rust.RustErasureStorage\$Session");val ctor=cls.declaredConstructors.single().apply{isAccessible=true}
  fun call(session:Any,name:String,vararg args:Any):Any?{val m=cls.declaredMethods.single{it.name==name}.apply{isAccessible=true};return try{m.invoke(session,*args)}catch(e:java.lang.reflect.InvocationTargetException){throw e.cause!!}}
  val end=runCatching{db.runInTransaction{entered.set(true);val session=ctor.newInstance(sql,"owner","owner");try{assertNotNull(runCatching{call(session,"defaults")}.exceptionOrNull());assertNotNull(runCatching{RustErasureStorage.apply(sql,"owner","owner")}.exceptionOrNull());val error=java.util.concurrent.atomic.AtomicReference<Throwable>();val t=Thread{try{call(session,"ready")}catch(e:Throwable){error.set(e)}};t.start();t.join(5000);assertFalse(t.isAlive);assertTrue(error.get()is IllegalStateException);call(session,"ready");assertNotNull(runCatching{call(session,"global",1)}.exceptionOrNull());for(i in 0..3)call(session,"global",i);assertNotNull(runCatching{call(session,"owned",-1)}.exceptionOrNull());for(i in 0..3)call(session,"owned",i);call(session,"receipts");assertEquals(true,call(session,"exists",0));assertNotNull(runCatching{call(session,"exists",1)}.exceptionOrNull());assertNotNull(runCatching{call(session,"stageDelete",1)}.exceptionOrNull());call(session,"stageDelete",0);assertEquals(false,call(session,"exists",1));assertNotNull(runCatching{call(session,"stageDelete",1)}.exceptionOrNull());assertEquals(true,call(session,"exists",2));call(session,"stageDelete",2);assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());call(session,"defaults");assertNotNull(runCatching{call(session,"outcome",0)}.exceptionOrNull());call(session,"outcome",1);call(session,"close");assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());throw IllegalStateException("adversarial rollback")}finally{call(session,"close");entered.remove()}}}.exceptionOrNull();assertEquals("adversarial rollback",end?.message);assertEquals(before,snapshot(db))}
 @Test fun actualHostOriginalControlSuccessAndDbFailureKeepDurableWipeGate()=runBlocking{RustTrackNative.warmUp();for(fault in listOf(false,true)){val owner="erase-owner-${UUID.randomUUID()}";val db=open();seed(db,owner);val prefs=AuthPreferences(context,context.getSharedPreferences("erase-prefs-${UUID.randomUUID()}",Context.MODE_PRIVATE),true).apply{userId=owner;isCloudSyncAllowed=true};val host=RustBoundRoomHost(prefs);val token=(host.publish(null,db,prefs.rustOperationSnapshot())as RustBoundRoomHost.Result.Value).value;val before=snapshot(db);var expected:List<List<String?>>?=null;val control=runCatching{db.runInTransaction{RustErasureRows.apply(db.openHelper.writableDatabase,owner,owner);expected=snapshot(db);throw IllegalStateException("original rollback")}}.exceptionOrNull();assertEquals("original rollback",control?.message);assertEquals(before,snapshot(db));if(fault)db.openHelper.writableDatabase.execSQL("CREATE TRIGGER fault AFTER INSERT ON cycle_settings BEGIN SELECT RAISE(ABORT,'erase fault'); END");val result=withContext(Dispatchers.IO){host.wipe(token)};assertEquals(if(fault)RustBoundRoomHost.Result.Storage else RustBoundRoomHost.Result.Value(Unit),result);assertEquals(if(fault)before else expected,snapshot(db));assertTrue(OwnerDataGate.isWiped(context,owner));assertFalse(prefs.isCloudSyncAllowed);assertTrue(prefs.hasPendingHealthSyncRevoke);assertFalse(host.isCurrent(token));assertEquals(RustBoundRoomHost.Result.Stale,withContext(Dispatchers.IO){host.wipe(token)});assertEquals(if(fault)before else expected,snapshot(db))}}
 @Test fun actualHostStaleOwnerHasNoDatabaseOrLifecycleEffects()=runBlocking{RustTrackNative.warmUp();val owner="erase-stale-${UUID.randomUUID()}";val db=open();seed(db,owner);val prefs=AuthPreferences(context,context.getSharedPreferences("erase-stale-${UUID.randomUUID()}",Context.MODE_PRIVATE),true).apply{userId=owner};val host=RustBoundRoomHost(prefs);val token=(host.publish(null,db,prefs.rustOperationSnapshot())as RustBoundRoomHost.Result.Value).value;val before=snapshot(db);val lifecycle=OwnerDataGate.snapshot(context,owner);prefs.userId="other-${UUID.randomUUID()}";assertEquals(RustBoundRoomHost.Result.Stale,withContext(Dispatchers.IO){host.wipe(token)});assertEquals(before,snapshot(db));assertEquals(lifecycle,OwnerDataGate.snapshot(context,owner))}
}
